import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.DdtnLau3.js";const b=JSON.parse('{"title":"规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/spec/index.md","filePath":"zh/spec/index.md"}'),i={name:"zh/spec/index.md"};function s(p,e,n,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h1><p>这些页面面向开发者，总结当前 Piwork 实现，依据源码项目已有规范编写，不另行定义 API 或包格式。</p><p>本页保留的历史 Linux 镜像组合使用固定发行标识 <code>0.0.7-62f2868cb8e2-d69916b52829-dirty</code>，包括 Core、可选 CLI、Agent、Files 和 Snapshots。Core 包含网页工作台、Admin 和首次引导。来源为 <code>62f2868cb8e24da3d08db7a7d6c00aabd6226cd4</code>，构建时 modified 为 true，输入 SHA256 为 <code>d69916b5282972c9a336745e4efc30b749fad531a42ed5aac3c8b4dcad4c38ff</code>；后续文档提交不改写这些实际构建身份。固定引用和可用状态见<a href="/piwork/piwork/install/0.0.7-62f2868cb8e2-d69916b52829-dirty/release-manifest.json">发行清单</a>。Web base 的独立<a href="/piwork/piwork/install/0.0.7-62f2868cb8e2-d69916b52829-dirty/web-base-release.json">发布记录</a>使用 NiceGUI，旧安装下载目录保持历史归属。</p><table tabindex="0"><thead><tr><th>范围</th><th>本站文档</th><th>权威来源</th></tr></thead><tbody><tr><td>可携带 Work</td><td><a href="/piwork/zh/spec/work.html">Work 规范</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">包格式</a>与 <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">portable-work</a></td></tr><tr><td>受管理能力</td><td><a href="/piwork/zh/spec/service.html">Service 规范</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/work-services/spec.md" target="_blank" rel="noreferrer">work-services</a>与 <a href="https://github.com/pphboy/piwork/blob/main/internal/servicemcp/tools.json" target="_blank" rel="noreferrer">MCP 工具</a></td></tr><tr><td>智能执行</td><td><a href="/piwork/zh/spec/harness.html">Harness 规范</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/agent-conversation/spec.md" target="_blank" rel="noreferrer">agent-conversation</a>与 <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/piwork-brain/spec.md" target="_blank" rel="noreferrer">piwork-brain</a></td></tr></tbody></table><h2 id="状态标记" tabindex="-1">状态标记 <a class="header-anchor" href="#状态标记" aria-label="Permalink to &quot;状态标记&quot;">​</a></h2><ul><li><strong>当前行为 / 格式：</strong> 已实现的行为和源码契约。</li><li><strong>实验性：</strong> 已有实现，但契约和交互还在演进。</li><li><strong>未来方向：</strong> 产品目标，不是已实现的保证。</li></ul><p>遇到不一致时，以当前实现为准。可以<a href="https://github.com/pphboy/piwork/issues" target="_blank" rel="noreferrer">提交 Issue</a>，附上命令、镜像版本和实际结果。</p><h2 id="当前交付边界" tabindex="-1">当前交付边界 <a class="header-anchor" href="#当前交付边界" aria-label="Permalink to &quot;当前交付边界&quot;">​</a></h2><p>Core 通过 Unix API 管理一台本地 Linux Docker Engine。统一应用面向 <code>linux/amd64</code> 和 Engine 28+，Linux/Windows 浏览器可远程连接；仅 Core Compose Demo 或高级 Compose 部署另需 Compose 2.24+。原生 Core 与 CLI 面向 Linux x86-64。独立桌面启动器在 Windows/Linux 本机运行 Linux 环境；原生边界见源码的 <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/cli-runtime-portability/spec.md" target="_blank" rel="noreferrer">CLI 平台契约</a>。</p><p>Work 需要就绪的运行镜像和模型配置。Core 关闭时会停止受管理的运行容器，并保留持久状态。关闭 Desktop 或 CLI 不会停止 Work。</p><p><a href="/piwork/zh/guide/quick-start.html">快速开始</a> 沿桌面一键启动路径进入 Piwork。Linux 服务端维护资料保留在<a href="/piwork/zh/guide/installation.html">安装与部署</a>及<a href="/piwork/zh/guide/source-installation.html">源码构建</a>。</p>',11)])])}const m=r(i,[["render",s]]);export{b as __pageData,m as default};
